  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('attention-control-test', 'Attention Control Test', 'Sustained focus and selective attention under distraction — a flanker-style interference task.', 'Attention Control Test is built on the Eriksen Flanker Task (Eriksen & Eriksen, 1974) — one of the most widely used paradigms for measuring selective attention and response inhibition. You identify the direction of a center arrow while ignoring surrounding "flanker" arrows that sometimes point the same way (congruent, easy) and sometimes point the opposite way (incongruent, harder) — the classic interference effect. Both accuracy and response speed are scored, since the point of the task is resisting the flankers'' pull quickly, not just eventually getting it right.', 'eye', v_cat, 'timed_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 10, 30, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'attention-control', 'Attention Control', 'Speed and accuracy identifying the target while ignoring flanking distractors.', true, 'logical', 1)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'The flanking arrows are pulling attention away from the center target more often than not, especially on incongruent trials — a common pattern that improves with practice.', ARRAY['Practice deliberately narrowing your focus to just the center position before glancing at the whole string', 'Slow down very slightly on trials that feel like they ''flash by'' — a rushed wrong answer costs more than a half-second of care', 'Notice whether errors cluster on incongruent trials specifically — that''s the interference effect, and it''s normal early on']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Congruent trials are handled well, but incongruent ones (where the flankers point the other way) cost accuracy or speed.', ARRAY['Practice sets weighted toward incongruent trials specifically to build resistance to the interference effect', 'Keep your gaze centered rather than scanning the whole arrow string left to right']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliable accuracy across both congruent and incongruent trials, with a modest speed cost on the harder ones — a normal, healthy interference pattern.', ARRAY['Push response speed further on congruent trials, where accuracy is already solid', 'This level of selective attention transfers directly to work environments full of visual distraction']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Fast and accurate on nearly every trial, including incongruent ones — minimal interference from the flanking distractors.', ARRAY['This is a strong, genuine selective-attention advantage — notice where it helps most in daily distraction-heavy tasks', 'Try the task again after a mentally fatiguing day to see how much the effect holds up under load']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Near-perfect speed and accuracy on every trial type — the flanking distractors barely register.', ARRAY['This level of attentional control is a genuine asset in high-distraction, high-stakes environments', 'Consider roles or tasks that specifically reward sustained selective attention under interference']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'attention-control', 'logical', 0.4);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":600}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Flanker Trials', 'Identify the direction of the CENTER arrow only, ignoring the arrows around it.', 'Answer as fast as you accurately can. The center arrow is what matters — the surrounding arrows are distractors and sometimes point the other way on purpose.', NULL, false, 1, 1);
  insert into scoring_rules (assessment_version_id, dimension_key, formula, section_weights, normalization, penalty_per_incorrect) values (v_ver, 'attention-control', 'sum'::scoring_formula, NULL, '{"min":0,"max":30}'::jsonb, NULL);
