  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('auditory-processing-speed', 'Auditory Processing Speed', 'How quickly and accurately you process spoken information — sequences, tones, and rapid verbal instructions.', 'Auditory Processing Speed combines two real, established auditory paradigms: WAIS/WMS Digit Span (Wechsler) — recalling a spoken digit sequence forward, then a separate set backward, the standard clinical measure of auditory working memory — and Wepman''s Auditory Discrimination Test (Wepman, 1958) — quickly judging whether two spoken words are the same or minimally different (like "pin" vs. "pen"), timed since the point is fast, accurate auditory discrimination, not eventually getting it right. Every sequence and word pair is real synthesized speech played through your device, not a text substitute.', 'ear', v_cat, 'timed_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 12, 20, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'auditory-processing', 'Auditory Processing', 'Composite score across digit span (forward and backward) and auditory discrimination.', true, 'memory', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'digit-span-forward', 'Digit Span Forward', 'Auditory working memory — recalling a spoken sequence in order.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'digit-span-backward', 'Digit Span Backward', 'Auditory working memory under mental manipulation — recalling a spoken sequence in reverse.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'auditory-discrimination', 'Auditory Discrimination', 'Speed and accuracy distinguishing same vs. minimally different spoken words.', false, NULL, 4)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Holding a spoken sequence in mind — especially in reverse — is difficult right now, and minimally-different word pairs are easy to mishear.', ARRAY['Practice with shorter sequences first (3-4 digits) before attempting longer ones', 'For backward spans, try picturing the digits appearing one at a time, then read them off in reverse from that mental image', 'Listen for the specific sound that differs in word pairs (first sound, middle vowel, last sound) rather than judging the whole word at once']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Shorter spans are manageable, but longer sequences and backward recall specifically show real strain.', ARRAY['Backward span is meant to be substantially harder than forward — a big gap between the two is normal, not a red flag', 'Practice minimal-pair listening specifically (many free speech-perception exercises use exactly this format)']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliable recall across most sequence lengths, both forward and backward, with solid auditory discrimination.', ARRAY['Push toward longer sequences (7+ digits) to find your actual ceiling', 'Notice whether forward or backward span is your relative strength — that''s informative about your auditory working-memory style']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Strong auditory working memory in both directions, plus fast, accurate discrimination of similar-sounding words.', ARRAY['This is a genuine asset for verbal-heavy, listening-intensive work — meetings, interpretation, live instruction-following', 'Compare this with your visual/spatial memory results — auditory and visual working memory don''t always track together']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Near-ceiling performance across digit span forward, backward, and auditory discrimination.', ARRAY['This is an elite auditory-processing result across every task type tested', 'Consider fields that specifically reward fast, accurate listening under real time pressure']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'auditory-processing', 'memory', 0.4);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Digit Span Forward', 'Listen to a spoken digit sequence, then recall it in the same order.', 'Each round plays once. Tap the digits back in the order you heard them.', NULL, false, 0.35, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Digit Span Backward', 'Listen to a spoken digit sequence, then recall it in reverse order.', 'Each round plays once. Tap the digits back in the REVERSE of the order you heard them — this is harder than it sounds.', NULL, false, 0.35, 2);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Auditory Discrimination', 'Quickly judge whether two spoken words are the same or different.', 'Listen carefully — some pairs differ by only one sound.', NULL, false, 0.3, 3);
  insert into scoring_rules (assessment_version_id, dimension_key, formula, section_weights, normalization, penalty_per_incorrect) values (v_ver, 'auditory-processing', 'average'::scoring_formula, NULL, NULL, NULL);
