  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('creative-assessment', 'Creative Assessment', 'Divergent thinking, originality, flexibility and problem reframing, with open-text responses and AI-assisted interpretation.', 'Creative Assessment measures divergent thinking, originality, flexibility, and problem-reframing ability through a mix of closed-form pattern/ideation items (deterministically scored) and open-ended written prompts (AI-interpreted only, never scored deterministically).', 'palette', v_cat, 'hybrid'::assessment_engine_type, 'medium'::assessment_difficulty, 15, 15, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'creative', 'Creative', 'Overall composite creativity score aggregating visual creativity, ideation, problem solving, flexibility, and innovation.', true, 'creative', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'visual-creativity', 'Visual Creativity', 'Pattern recognition and aesthetic sense, measured through visual pattern completion and image-selection items.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'ideation', 'Ideation', 'Idea generation and divergent thinking, measured through alternative-uses and brainstorming items.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'problem-solving', 'Problem Solving', 'Creative and analytical approaches to solving constrained or contradictory problems.', false, NULL, 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'flexibility', 'Flexibility', 'Adaptability and openness to changing approach, especially after negative feedback or a failed first attempt.', false, NULL, 5)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'innovation', 'Innovation', 'Novel thinking and risk-taking when facing seemingly impossible challenges.', false, NULL, 6)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Your creative thinking is still emerging. You tend to favor familiar, well-trodden solutions over novel ones, and may hesitate to change course once you''ve picked an approach.', ARRAY['Practice brainstorming without judging ideas — quantity first, quality later.', 'Deliberately generate multiple unrelated uses for everyday objects.', 'Seek out feedback and treat it as raw material rather than criticism.']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'You show a moderate capacity for creative thinking, with occasional flashes of originality, but your ideas often stay close to conventional patterns.', ARRAY['Push past your first three ideas — the most original ones tend to come later.', 'Try reframing problems from a completely different perspective before solving them.', 'Expose yourself to unfamiliar visual styles and disciplines regularly.']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'You demonstrate solid creative range — comfortable generating alternatives, spotting patterns, and adjusting your approach when something isn''t working.', ARRAY['Stretch further into unconventional or paradox-embracing solutions.', 'Pair your idea generation with faster experimentation cycles.', 'Mentor others in divergent-thinking techniques to sharpen your own.']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'You think fluently and flexibly, generating many original ideas and reframing problems with ease. You''re comfortable with ambiguity and contradiction.', ARRAY['Channel your fluency into structured creative projects with real constraints.', 'Explore cross-domain inspiration to keep pushing originality further.', 'Practice articulating the ''why'' behind your creative choices for collaborators.']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Your creative thinking is exceptional — highly original, fluent, and adaptable across visual, verbal, and problem-solving domains.', ARRAY['Take on ambiguous, high-stakes creative challenges that stretch your range.', 'Share your process to help build creative capacity in others.', 'Protect deliberate space for unstructured exploration to sustain originality.']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'creative', 'creative', 1);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Core Creative Assessment', 'Closed-form items covering visual pattern recognition, ideation, problem solving, flexibility, and innovation, each scored deterministically.', 'Choose the option that best fits each prompt. Some items include an image or a slider scale.', NULL, false, 0.7, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Creative Expression', 'Open-ended written prompts that surface divergent thinking and imaginative expression. These responses are AI-interpreted and do not contribute to the deterministic score.', 'Write freely — there are no right or wrong answers here.', NULL, false, 0.3, 2);
