  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Inference', 'Judging the degree of truth or falsity of inferences drawn from a set of facts, without assuming anything beyond what''s stated.', 'Based only on the facts given, judge whether each conclusion is true, probably true, insufficient data, probably false, or false. Pick the single best judgment.', NULL, false, 0.2, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Recognition of Assumptions', 'Identifying the unstated assumption that a claim depends on.', 'For each statement, decide which assumption is actually being made — not just something that sounds reasonable.', NULL, false, 0.2, 2);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Deduction', 'Determining whether a conclusion follows necessarily from given premises, using formal validity rather than real-world plausibility.', 'Assume the premises are true. Judge only whether the conclusion follows necessarily from them.', NULL, false, 0.2, 3);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Interpretation', 'Weighing evidence to decide whether a proposed conclusion follows beyond reasonable doubt.', 'Decide whether each conclusion follows from the passage beyond a reasonable doubt, based only on the information given.', NULL, false, 0.2, 4);
