  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Scenario Judgment', 'Realistic snap decisions made with incomplete information.', 'Choose the best immediate action given only what''s stated.', NULL, false, 0.33, 2);
