  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong Emotional Intelligence', 'You demonstrate strong emotional awareness and management skills, handling both your own emotions and those of others with confidence in most situations.', ARRAY['Refine your ability to remain objective when emotions run high', 'Use positive emotions deliberately to boost creativity and decision quality', 'Continue strengthening close, mutually satisfying relationships']::text[], NULL, 4);
