  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('full-iq-estimation-report', 'Full IQ Estimation Report', 'A comprehensive, multi-battery composite drawing on every completed assessment to estimate a full-scale IQ range.', 'Full IQ Estimation Report doesn''t ask its own questions — it computes a composite from the Logical, Verbal, Spatial, and Memory scores in your existing Brain Profile, the same four cognitive-ability domains real full-scale IQ batteries combine (e.g. the WAIS''s Verbal Comprehension, Perceptual Reasoning, Working Memory, and Processing Speed indices). Emotional Intelligence and Creative scores are deliberately excluded from this composite, the same way Palmistry is excluded from the Brain Profile aggregate — they measure real things, just not what "IQ" traditionally refers to.', 'file-text', v_cat, 'ai_analysis'::assessment_engine_type, 'hard'::assessment_difficulty, 45, 1, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'iq-composite', 'Full-Scale Composite Estimate', 'Average of your Logical, Verbal, Spatial, and Memory Brain Profile scores — not scored from a new test.', false, NULL, 1)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 5, 'Not Enough Data Yet', 'You haven''t completed enough of the four core assessments (Logical Reasoning or Abstract Reasoning Pro or Fluid Intelligence Peak, Verbal Reasoning or Verbal Intelligence, Spatial Intelligence or Visuospatial Rotation, Memory Recall) for a meaningful composite. Complete at least 3 of those 4 domains, then come back.', ARRAY['Complete at least one assessment in each of the Logical, Verbal, Spatial, and Memory categories', 'The more of the ten-plus assessments in each domain you complete, the more stable this composite becomes', 'This report re-checks your data every time you take it — no need to "reset" anything']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 6, 30, 'Estimated range: below 90', 'Based on your completed assessments across the four core domains. Remember this is a self-reflection estimate, not a clinically validated IQ score — this platform has no standardization sample behind it.', ARRAY['Look at your Brain Profile page for which specific domain is pulling the composite down', 'Complete more assessments in your weaker domain(s) — this composite updates automatically as you do']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Estimated range: 90-100', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['Check your Brain Profile for your strongest and weakest of the four core domains', 'Retaking assessments you''ve improved on since your first attempt will refresh this composite']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Estimated range: 100-115', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['This composite reflects fairly balanced performance across Logical, Verbal, Spatial, and Memory', 'Consider Fluid Intelligence Peak or Verbal Reasoning Mastery if you want to stress-test your ceiling in a specific domain']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Estimated range: 115-130', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['A strong composite across all four domains — check your Brain Profile to see if one domain leads the others', 'For an actual clinical or professionally normed IQ score, a licensed psychologist administering a standardized instrument is the real route — this report doesn''t replace that']::text[], NULL, 5);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Estimated range: 130+', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['An exceptional composite across Logical, Verbal, Spatial, and Memory domains', 'As with any tier here: this is a self-assessment composite, not a substitute for a professionally administered, normed IQ test']::text[], NULL, 6);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Before You Continue', 'A one-step confirmation before generating your composite.', 'This isn''t a new test — it reads your existing results.', NULL, false, 1, 1);
  insert into scoring_rules (assessment_version_id, dimension_key, formula, section_weights, normalization, penalty_per_incorrect) values (v_ver, 'iq-composite', 'custom'::scoring_formula, NULL, NULL, NULL);
  insert into assessment_questions (assessment_version_id, section_id, question_id, "order", weight) values
    (v_ver, (select id from assessment_sections where assessment_version_id = v_ver and name = 'Before You Continue'), (select id from questions where external_key = 'fier-ack-01'), 1, 1);
  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('intelligence-profile', 'EvalOtter Intelligence Profile', 'The flagship assessment. Combines logical reasoning, numerical intelligence, memory, verbal reasoning, spatial intelligence, and pattern recognition into one EvalOtter Score.', 'The EvalOtter Intelligence Profile is the flagship assessment — a broad first read across six cognitive domains: logical reasoning, numerical intelligence, memory, verbal reasoning, spatial intelligence, and pattern recognition. It draws a curated subset of questions from the platform''s shared question library (the same items used in the dedicated single-domain assessments), so results are directly comparable to your scores on those assessments. EvalOtter assessments are designed for education, entertainment and self-discovery and are not a substitute for professional psychological, medical or clinical assessment.', 'brain', v_cat, 'hybrid'::assessment_engine_type, 'medium'::assessment_difficulty, 25, 15, true, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'logical', 'Logical', 'Pattern detection and deductive inference.', true, 'logical', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'numerical', 'Numerical', 'Arithmetic, percentages, ratios, and sequences.', true, 'logical', 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'memory', 'Memory', 'Word and sequence recall.', true, 'memory', 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'verbal', 'Verbal', 'Vocabulary and word precision.', true, 'verbal', 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'spatial', 'Spatial', 'Visual matrix pattern completion.', true, 'spatial', 5)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Your broad cognitive profile is still forming across the domains tested. This first read is a starting point, not a verdict — the dedicated single-domain assessments will show you exactly where to focus.', ARRAY['Take the dedicated assessment for your lowest-scoring domain to get a fuller picture.', 'Revisit this profile after practicing in your weaker areas.', 'Use the Brain Profile radar to see your shape at a glance, not just one number.']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'You show typical performance across most cognitive domains tested, with some unevenness between your strongest and weakest areas.', ARRAY['Check your Brain Profile to see which domain is pulling the average down.', 'Take the single-domain assessments for a more precise read on each area.', 'Revisit this profile periodically to track how your shape changes over time.']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'You perform solidly across logical, numerical, memory, verbal, and spatial reasoning, with a reasonably balanced profile.', ARRAY['Take the dedicated assessments to sharpen your understanding of each individual domain.', 'Look at your Brain Profile radar for your single strongest area and lean into it.', 'Retake periodically — this composite is a good way to track overall change over time.']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'You perform well above average across the cognitive domains tested, with a well-rounded profile and no clear weak spot.', ARRAY['Take the single-domain assessments to find your single sharpest edge.', 'Explore Emotional Intelligence and Creative Assessment to round out your full Brain Profile.', 'Consider what real-world contexts would let you apply this range of ability.']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'You perform exceptionally across logical, numerical, memory, verbal, and spatial reasoning — a rare, well-rounded profile in the top tier of this assessment.', ARRAY['Explore the full catalogue — Emotional Intelligence and Creative Assessment measure dimensions this profile doesn''t touch.', 'Take the single-domain assessments to see just how deep each individual strength runs.', 'Revisit periodically; a broad composite like this is a good long-term benchmark.']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'logical', 'logical', 0.6);
