  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('memory-recall', 'Memory Recall', 'Word, image and number-sequence recall exercises adapted from clinical memory tests like ISLT and ADAS-Cog word recall.', 'Memory Recall is a comprehensive cognitive assessment inspired by standardized memory tests: the ISLT Shopping List Test, ADAS-Cog Word Recall, a Logical Memory story-recall test, an SKT-style speed naming and object recognition task, and a SAGE-style general cognitive screen.', 'sparkles', v_cat, 'memory_exercise'::assessment_engine_type, 'medium'::assessment_difficulty, 12, 24, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'memory', 'Memory', 'Composite memory score aggregating immediate recall, delayed/story recall, sequence memory, and general cognitive screening performance across all sub-tests.', true, 'memory', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'immediate-recall', 'Immediate Recall', 'Ability to encode and immediately recognize/recall newly presented items (ISLT shopping list recognition, ADAS-Cog free word recall).', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'delayed-recall', 'Delayed / Story Recall', 'Ability to retain and answer detail-oriented questions about a short narrative after a 45-second delay.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'sequence-memory', 'Sequence & Object Memory', 'Speed of object naming and subsequent recognition of a sequentially presented object set.', false, NULL, 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'sage-composite', 'General Cognitive Screen', 'Broad cognitive screening performance across orientation, calculation, pattern, language, visual, reasoning, and memory items.', false, NULL, 5)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Recall and recognition performance across shopping list, word list, story, and object tasks was well below typical range, suggesting memory encoding or retrieval may benefit from focused attention.', ARRAY['Practice daily recall exercises like repeating shopping lists or short stories back to yourself', 'Break new information into smaller chunks before trying to remember it', 'Reduce distractions during tasks that require you to remember new information']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'You recalled a moderate share of shopping list items, word list items, and story details — performance consistent with typical everyday memory demands but with room to strengthen retention.', ARRAY['Use association techniques (linking new items to familiar images) to boost recall', 'Revisit and rehearse new information within a few hours of learning it', 'Get consistent sleep, which strengthens memory consolidation']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'You correctly recognized most shopping list and object items and recalled the majority of word list and story details, indicating solid immediate and delayed recall abilities.', ARRAY['Challenge yourself with longer lists or more complex stories to keep improving', 'Practice free recall (without options) rather than just recognition to build retrieval strength', 'Maintain habits like reading and puzzles that keep memory circuits active']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'You recalled nearly all items across the shopping list, word list, story, and object recognition tasks, reflecting well above average encoding and retrieval performance.', ARRAY['Take on advanced memory challenges, such as memorizing longer sequences or multiple lists at once', 'Teach or quiz others using recall techniques to reinforce your own retention', 'Keep varying the type of material you practice recalling']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'You achieved near-perfect recall and recognition across shopping list, word list, story detail, and object memory tasks — performance in the top tier of this assessment.', ARRAY['Explore competitive or advanced memory training (e.g., memory championship techniques)', 'Use your strong recall ability to support learning in other high-value areas of life', 'Mentor others in memory strategies that have worked for you']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'memory', 'memory', 1);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'ISLT Shopping List', 'International Shopping List Test — participants study a 12-item shopping list, then attempt to recognize the items from a mixed grid of targets and distractors.', 'You will see 12 shopping list items for 30 seconds. Study them carefully. Afterward, select the items you remember from a grid of 20 items (12 targets + 8 distractors).', 30, false, 0.2, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'ADAS-Cog Word Recall', 'Alzheimer''s Disease Assessment Scale-Cognitive word list test — 10 words are shown sequentially, then freely recalled by typing.', '10 words will be displayed one at a time, 3 seconds each. After all words have been shown, type as many as you can remember, in any order.', 30, false, 0.2, 2);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Logical Memory Test', 'Wechsler-style Logical Memory subtest — a short news-style story is read, then comprehension/recall questions are answered about its details.', 'Read the story ''The Brave Firefighter'' carefully. You have 45 seconds. Afterward, answer 5 multiple-choice questions about details from the story.', 45, false, 0.2, 3);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'SKT Speed Test', 'Syndrom-Kurztest-inspired speed naming and object recognition task — 8 objects are named as quickly as possible, then recognized from a mixed grid.', 'You will be shown 8 objects one at a time. Select the correct name for each as quickly as possible. Afterward, identify which objects you saw from a mixed grid of 14 (8 targets + 6 distractors).', NULL, false, 0.2, 4);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'SAGE Assessment', 'Self-Administered Gerocognitive Exam-inspired mixed cognitive screen covering orientation, calculation, pattern recognition, language, visual, reasoning, and memory items.', 'Answer each question by selecting one option. Includes one item testing recall of the earlier ISLT shopping list.', NULL, false, 0.2, 5);
