  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Same or Different', 'Judge whether two strings are identical.', 'Answer as fast as you accurately can.', NULL, false, 0.25, 1);
